import pytest

from missing import find_missing  # update module name if needed


@pytest.mark.parametrize(
    ("nums", "expected"),
    [
        ([3, 0, 1], 2),                         # missing middle
        ([0, 1], 2),                            # missing last
        ([1, 2], 0),                            # missing first
        ([0, 2], 1),                            # small gap
        ([0, 1, 2], 3),                         # already sorted
        ([9, 6, 4, 2, 3, 5, 7, 0, 1], 8),       # larger unordered input
    ],
)
def test_find_missing_happy_paths(nums, expected):
    assert find_missing(nums) == expected


@pytest.mark.parametrize(
    ("nums", "expected"),
    [
        ([], 0),     # sequence [0], missing 0
        ([0], 1),    # sequence [0, 1], missing 1
        ([1], 0),    # sequence [0, 1], missing 0
    ],
)
def test_find_missing_edge_cases(nums, expected):
    assert find_missing(nums) == expected


def test_find_missing_all_positions_small_sequences():
    for n in range(10):
        for missing in range(n + 1):
            nums = [x for x in range(n + 1) if x != missing]
            assert find_missing(nums) == missing


def test_find_missing_large_sequence():
    n = 10_000
    missing = 7_777
    nums = [x for x in range(n + 1) if x != missing]

    assert find_missing(nums) == missing


def test_find_missing_does_not_mutate_input():
    nums = [4, 0, 2, 1]
    original = nums.copy()

    assert find_missing(nums) == 3
    assert nums == original


@pytest.mark.parametrize(
    "bad_input",
    [
        pytest.param(None, id="none"),
        pytest.param(123, id="integer"),
        pytest.param(iter([0, 1]), id="iterator_without_len"),
    ],
)
def test_find_missing_raises_type_error_for_invalid_input_object(bad_input):
    with pytest.raises(TypeError):
        find_missing(bad_input)


@pytest.mark.parametrize(
    "nums",
    [
        pytest.param([0, "1"], id="string_element"),
        pytest.param([None], id="none_element"),
        pytest.param([0, object()], id="object_element"),
    ],
)
def test_find_missing_raises_type_error_for_non_numeric_elements(nums):
    with pytest.raises(TypeError):
        find_missing(nums)
